<script>
const costCentres=@json($costCentres),department=document.querySelector('#department'),costCentre=document.querySelector('#cost-centre');
const definitions=@json($entryTypes),purchaseSubAccounts=@json($purchaseSubAccounts),purchaseSettlementAccounts=@json($purchaseSettlementAccounts),farmAccounts=@json($farmAccounts),category=document.querySelector('#transaction-category'),group=document.querySelector('#account-group'),account=document.querySelector('#entry-account'),groupLabel=document.querySelector('#account-group-label'),accountLabel=document.querySelector('#entry-account-label'),subAccountField=document.querySelector('#sub-account-field'),subAccount=document.querySelector('#sub-account'),partyLabel=document.querySelector('#party-label'),methodField=document.querySelector('#method-field'),paymentMethod=document.querySelector('#payment-method'),paymentAccountField=document.querySelector('#payment-account-field'),paymentAccount=document.querySelector('#payment-account'),paymentAccountLabel=document.querySelector('#payment-account-label'),settlementHint=document.querySelector('#settlement-hint'),receiptField=document.querySelector('#receipt-field'),paymentKindField=document.querySelector('#payment-kind-field'),receiptKind=document.querySelector('#receipt-kind'),paymentKind=document.querySelector('#payment-kind'),dueField=document.querySelector('#due-field'),billField=document.querySelector('#bill-field'),due=document.querySelector('#due'),bill=document.querySelector('#bill'),quantity=document.querySelector('#quantity'),unitPrice=document.querySelector('#unit-price'),amount=document.querySelector('#amount');
const partyInput=document.querySelector('#party-input'),partyHint=document.querySelector('#party-hint'),referenceLabel=document.querySelector('#reference-label'),referenceHint=document.querySelector('#reference-hint');
const stockToggleField=document.querySelector('#stock-toggle-field'),trackInventory=document.querySelector('#track-inventory'),stockStoreField=document.querySelector('#stock-store-field'),inventoryStore=stockStoreField.querySelector('select'),stockUnitField=document.querySelector('#stock-unit-field'),inventoryUnit=document.querySelector('#inventory-unit'),stockLocationField=document.querySelector('#stock-location-field'),inventoryLocation=document.querySelector('#inventory-location');
const quantityField=document.querySelector('#quantity-field'),unitPriceField=document.querySelector('#unit-price-field');
function options(select,values,selected=''){select.innerHTML='';values.forEach(value=>select.add(new Option(value,value,value===selected,value===selected)));}
function syncCostCentres(){const selected=department.options[department.selectedIndex],code=selected?.dataset.code||'',items=costCentres[code]||[];options(costCentre,items,'{{ old('cost_centre') }}');costCentre.disabled=!items.length;if(!items.length)costCentre.add(new Option(department.value?'No units configured':'Choose department first',''));}
function syncSupplier(){const purchase=category.value==='purchase',banking=category.value==='banking',equity=category.value==='capital_and_equity';partyLabel.textContent=purchase?'Supplier':(banking?'Destination account':definitions[category.value].party);partyInput.placeholder=purchase?'Type or choose a supplier':(banking?'Type destination, e.g. Cash on Hand':(equity?'Enter owner or shareholder name':'Type or choose a customer'));partyHint.textContent=purchase?'Choose a listed supplier or type a new supplier name directly.':'Choose an existing name or type a new one.';if(equity)partyInput.removeAttribute('list');else partyInput.setAttribute('list',purchase?'finance-supplier-list':(banking?'banking-account-list':'finance-customer-list'));}
function syncStock(){const purchase=category.value==='purchase',tracked=purchase&&trackInventory.checked;stockToggleField.hidden=!purchase;trackInventory.disabled=!purchase;stockStoreField.hidden=!tracked;stockUnitField.hidden=!tracked;stockLocationField.hidden=!tracked;inventoryStore.required=tracked;inventoryUnit.required=tracked;inventoryLocation.required=tracked;}
function syncSubAccount(){const items=category.value==='purchase'?(purchaseSubAccounts[account.value]||[]):[];subAccountField.hidden=!items.length;subAccount.disabled=!items.length;subAccount.required=items.length>0;if(items.length)options(subAccount,items,'{{ old('sub_account') }}');}
function syncSettlement(){const purchase=category.value==='purchase',equity=category.value==='capital_and_equity',items=purchase?(purchaseSettlementAccounts[account.value]||[]):farmAccounts;options(paymentAccount,items,'{{ old('account') }}');paymentAccountLabel.textContent=purchase?'Settlement account':(equity?'Farm cash / bank account':'Payment / receiving account');settlementHint.textContent=purchase?'Choose paid now, credit/payable, or prepayment.':(equity?'The farm account receiving or paying the money.':'');}
function syncPaymentMethod(){if(paymentMethod.value==='in_kind'){if(!Array.from(paymentAccount.options).some(option=>option.value==='In-kind / Barter Clearing'))paymentAccount.add(new Option('In-kind / Barter Clearing','In-kind / Barter Clearing'));paymentAccount.value='In-kind / Barter Clearing';paymentAccount.disabled=true;settlementHint.textContent='Describe what was received or given and enter its fair UGX value.';}else paymentAccount.disabled=false;}
function syncEquity(){if(category.value!=='capital_and_equity')return;const reserve=account.value==='Reserve Transfer';methodField.hidden=reserve;paymentAccountField.hidden=reserve;paymentAccount.required=!reserve;partyInput.required=true;settlementHint.textContent=reserve?'No cash account is required for an internal reserve transfer.':'Choose the farm account affected by this owner/shareholder transaction.';}
function syncAccount(){const items=definitions[category.value].groups[group.value]||[];options(account,items.length?items:['Other / Unclassified'],'{{ old('entry_account') }}');syncSubAccount();syncSettlement();syncEquity();}
function syncRelated(){dueField.hidden=category.value!=='revenue'||receiptKind.value!=='customer_payment';billField.hidden=category.value!=='purchase'||paymentKind.value!=='supplier_bill';due.disabled=dueField.hidden;bill.disabled=billField.hidden;}
function sync(){const entry=definitions[category.value],selected=group.value||'{{ old('account_group') }}';options(group,Object.keys(entry.groups),selected);const equity=category.value==='capital_and_equity',prepayment=category.value==='customer_prepayment';groupLabel.textContent=equity?'Transaction class':'Account group';accountLabel.textContent=equity?'Capital / equity action':'Account / item';partyLabel.textContent=entry.party;syncSupplier();syncStock();const purchase=category.value==='purchase',revenue=category.value==='revenue',banking=category.value==='banking',cash=['money_received','money_paid'].includes(entry.ledger_type),noQuantity=banking||equity||prepayment;quantityField.hidden=noQuantity;unitPriceField.hidden=noQuantity;quantity.disabled=noQuantity;unitPrice.disabled=noQuantity;referenceLabel.textContent=purchase?'Voucher Number':((revenue||prepayment)?'Receipt / reference number':'Reference number');referenceHint.textContent=prepayment?'Enter the receipt, bank, or mobile-money reference for the advance received.':(purchase?'The same voucher number may be used for several expenses covered by that voucher.':(banking?'Use the withdrawal slip, deposit slip, or bank transaction reference.':(equity?'Use the deposit slip, payment reference, board resolution, or supporting document.':'Enter the source document number.')));methodField.hidden=!cash&&!equity;paymentAccountField.hidden=!cash&&!equity;paymentAccount.required=cash||equity;receiptField.hidden=!revenue;paymentKindField.hidden=!purchase;syncAccount();syncRelated();}
function calculate(){if(quantity.value&&unitPrice.value!=='')amount.value=(Number(quantity.value)*Number(unitPrice.value)).toFixed(2);}
document.querySelector('#finance-entry').addEventListener('submit',()=>{document.querySelector('#ledger-account').value=paymentAccountField.hidden?account.value:(paymentMethod.value==='in_kind'?'In-kind / Barter Clearing':paymentAccount.value);paymentAccount.disabled=false;});department.addEventListener('change',syncCostCentres);category.addEventListener('change',()=>{sync();syncPaymentMethod();});group.addEventListener('change',syncAccount);account.addEventListener('change',()=>{syncSubAccount();syncSettlement();syncEquity();syncPaymentMethod();});paymentMethod.addEventListener('change',syncPaymentMethod);trackInventory.addEventListener('change',syncStock);receiptKind.addEventListener('change',syncRelated);paymentKind.addEventListener('change',syncRelated);quantity.addEventListener('input',calculate);unitPrice.addEventListener('input',calculate);syncCostCentres();sync();syncPaymentMethod();
</script>
